//! Control-key pin verification (re-exported from `tm_keys::pin`).

pub use tm_keys::pin::{verify_pin, verify_pin_hex, decode_pin_hex, PinError, PIN_BLOB_LEN, PIN_BODY_LEN, PIN_HEX_LEN};

/// Ed25519 public key that signs control-key pin blobs.
/// Generated by tools/gen_fingerprint.py. An all-zero key is rejected at
/// verify time (PinError::PlaceholderVerifyKey), so an unconfigured build
/// fails closed instead of trusting an unsigned blob.
pub const PIN_VERIFY_KEY: [u8; 32] = [0x82, 0xdd, 0x26, 0xd0, 0x35, 0xf4, 0x64, 0xb1, 0x0c, 0x2c, 0xe1, 0xc4, 0xdd, 0xe6, 0xb7, 0x2a, 0x71, 0x50, 0x9e, 0x76, 0xa0, 0x2e, 0xed, 0x8b, 0x58, 0x75, 0xf0, 0xd2, 0xb3, 0xec, 0xba, 0x0b];
